(function(){
 const API='https://intranet.tiendasimportados.com',dialog=document.querySelector('.pqrs-dialog'),form=document.getElementById('pqrs-form'),feedback=form.querySelector('.form-demo-feedback'),submit=form.querySelector('.dialog-submit'),connection=form.querySelector('.pqrs-connection');
 let config,widget=null,token='',consult=false,sending=false,requestId=crypto.randomUUID(),code=crypto.randomUUID().replaceAll('-','');
 const statuses={received:'Recibida',in_review:'En revisión',awaiting_information:'Esperando información',completed:'Completada',closed:'Cerrada'};
 const message=text=>{feedback.textContent=text;feedback.hidden=false;};
 async function verify(){token='';submit.disabled=true;try{config ||= await (await fetch(API+'/api/public/config',{signal:AbortSignal.timeout(10000)})).json();if(!config.enabled||!config.siteKey)throw Error();await window.ImportadosVerification.load();if(widget!==null)window.turnstile.remove(widget);widget=window.turnstile.render('#pqrs-verification',{sitekey:config.siteKey,size:'compact',language:'es',action:consult?'pqrs_lookup':'pqrs_submit',callback:value=>{token=value;submit.disabled=false;},'expired-callback':()=>{token='';submit.disabled=true;},'error-callback':()=>{token='';submit.disabled=true;connection.textContent='No pudimos verificar la conexión. Vuelve a abrir el formulario para reintentar.';}});connection.textContent='La respuesta estará disponible mediante el radicado y el código. No enviamos avisos automáticos por correo.';}catch{connection.textContent='La recepción está temporalmente fuera de línea. Intenta más tarde.';}}
 document.querySelectorAll('[data-pqrs]').forEach(button=>button.addEventListener('click',()=>{if(sending)return;consult=button.dataset.pqrs==='consultar';document.getElementById('pqrs-dialog-title').textContent=consult?'Consultar una solicitud':'Radicar una solicitud';form.querySelector('.radicar-fields').hidden=consult;form.querySelector('.radicar-fields').disabled=consult;form.querySelector('.consultar-fields').hidden=!consult;form.querySelector('.consultar-fields').disabled=!consult;submit.textContent=consult?'Consultar solicitud':'Enviar solicitud';feedback.hidden=true;dialog.showModal();verify();}));
 dialog.addEventListener('cancel',event=>{if(sending)event.preventDefault();});
 dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
 form.addEventListener('submit',async e=>{e.preventDefault();if(sending||!token||!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.token=token;if(!consult){data.consent=data.consent==='on';data.request_id=requestId;data.consultation_code=code;}else{data.case_number=data.case_number.trim().toUpperCase();data.consultation_code=data.consultation_code.trim();}sending=true;dialog.querySelector('.dialog-close').disabled=true;submit.disabled=true;const fieldset=form.querySelector(consult?'.consultar-fields':'.radicar-fields');fieldset.disabled=true;feedback.hidden=true;submit.textContent=consult?'Consultando…':'Guardando solicitud…';try{const r=await fetch(API+(consult?'/api/pqrs/lookup':'/api/pqrs'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(30000)});const result=await r.json();if(!r.ok||!result.ok)throw Error(result.message||'No pudimos confirmar la operación. Intenta nuevamente.');if(consult){const item=result.case;message('Radicado: '+item.case_number+'\nEstado: '+(statuses[item.status]||item.status)+'\nAsunto: '+item.subject+'\n\n'+(item.response_message?'Respuesta de Importados:\n'+item.response_message:'Aún no hay una respuesta registrada. Puedes consultar nuevamente más adelante.'));}else{message('Recibimos tu solicitud. Guarda estos datos antes de cerrar:\n\nRadicado: '+result.case_number+'\nCódigo de consulta: '+result.consultation_code+'\n\nCon ambos puedes revisar tu estado y nuestra respuesta.');form.reset();requestId=crypto.randomUUID();code=crypto.randomUUID().replaceAll('-','');}}catch(error){message(error.message||'No pudimos confirmar la operación. Intenta nuevamente.');}finally{sending=false;dialog.querySelector('.dialog-close').disabled=false;fieldset.disabled=false;submit.textContent=consult?'Consultar solicitud':'Enviar solicitud';token='';if(widget!==null)window.turnstile.reset(widget);}});
 if(new URLSearchParams(window.location.search).get("pqrs")==="radicar")document.querySelector('[data-pqrs="radicar"]')?.click();
})();
